do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-055","project":"qvplwejffhjvxaypmjut","actions":[{"ref":"w0","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL719942W"},"before":null,"after":{"title":"De zaterdagvliegers","author_id":654,"first_publish_year":1981,"open_library_id":"OL719942W","cover_id":null,"source_type":"open_library","work_type":"collection","native_identity_key":"nlscale:20261102:ol:OL719942W"}},{"ref":"e0","relation":"editions","key":{"open_library_edition_id":"OL3870103M"},"before":null,"after":{"work_id":"@w0","open_library_edition_id":"OL3870103M","isbn_13":"9789029518284","isbn_10":null,"title":"De zaterdagvliegers","language":"dut","publisher":"De Arbeiderspers"}},{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":"@w0","language":"nl"},"before":null,"after":{"work_id":"@w0","language":"nl","bound_author_id":654,"text":"Maarten ’t Hart brengt verhalen samen over jeugdherinneringen, zijn werk als bioloog, het schrijverschap en zijn tijd voor de klas. Kleine gebeurtenissen krijgen betekenis door nauwkeurige aandacht voor mensen, dieren en de omgeving. In het titelverhaal kijkt een verteller terug op buurtbewoners en de verschillen tussen duivenliefhebbers die op zaterdag of op zondag vliegen. De bundel verkent hoe waarnemen vertrouwde overtuigingen kan veranderen. De afzonderlijke verhalen vormen geen doorlopende roman, maar tonen verschillende kanten van een persoonlijke leefwereld.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.dbnl.org/tekst/_vri013boek01_01/_vri013boek01_01_0283.php","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p810871424"],"reference":"new-work-dossier-readings-055.json#153","checked_at":"2026-11-03T11:33:23.968Z","note":"Genuine separate 1981 collection by Maarten ''t Hart; reuse actual original-content review content-amendment-015.json.